<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Emberline — a three.js tactical FPS</title>
<style>
  /* Look plan: canvas, surface, hairline, ink, muted and one amber accent, plus the
     two team colours and a danger red. Every colour below is one of the nine. */
  :root {
    --canvas: #14161a;
    --surface: #1e2228;
    --hairline: #2c323a;
    --ink: #e9e6df;
    --muted: #98a0a8;
    --accent: #f0a830;
    --vanguard: #8fb8d8;
    --ember: #e07840;
    --danger: #d95f4b;
    --radius-panel: 4px;
    --radius-control: 8px;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    overflow: hidden;
    background: var(--canvas);
    color: var(--ink);
    font-family: var(--font-ui);
  }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; }

  #crosshair { position: fixed; left: 50%; top: 50%; width: 22px; height: 22px; transform: translate(-50%, -50%); --gap: 5px; }
  #crosshair i { position: absolute; background: var(--ink); opacity: .9; }
  #crosshair i:nth-child(1) { left: 10px; top: calc(10px - var(--gap) - 7px); width: 2px; height: 7px; }
  #crosshair i:nth-child(2) { left: 10px; top: calc(12px + var(--gap)); width: 2px; height: 7px; }
  #crosshair i:nth-child(3) { top: 10px; left: calc(10px - var(--gap) - 7px); height: 2px; width: 7px; }
  #crosshair i:nth-child(4) { top: 10px; left: calc(12px + var(--gap)); height: 2px; width: 7px; }
  #crosshair::after { content: ''; position: absolute; left: 10px; top: 10px; width: 2px; height: 2px; background: var(--ink); }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; transition: opacity 90ms linear; }
  #hitmarker.on { opacity: 1; }
  #hitmarker.kill i { background: var(--danger); }
  #hitmarker i { position: absolute; background: var(--accent); }
  #hitmarker i:nth-child(1) { left: 12px; top: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 8px; }
  #hitmarker i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 8px; }

  #damage-flash { position: fixed; inset: 0; pointer-events: none; opacity: 0; transition: opacity 120ms linear;
    background: radial-gradient(ellipse at center, transparent 55%, rgba(217, 95, 75, .45) 100%); }
  #damage-flash.on { opacity: 1; }

  #health { position: fixed; left: 32px; bottom: 24px; width: 220px; }
  #health-bar { height: 8px; background: var(--hairline); border-radius: 4px; overflow: hidden; }
  #health-fill { height: 100%; width: 100%; background: var(--ink); transition: width 120ms linear; }
  #health-fill.low { background: var(--danger); }
  #health-line { display: flex; gap: 12px; margin-top: 6px; font-family: var(--font-readout); font-size: 14px; }
  #health-value { font-size: 28px; line-height: 1; }
  #armor-value { color: var(--vanguard); align-self: end; }

  #ammo { position: fixed; right: 32px; bottom: 24px; text-align: right; }
  #ammo-line { display: flex; align-items: baseline; gap: 8px; justify-content: flex-end;
    font-family: var(--font-readout); font-size: 56px; line-height: 1; letter-spacing: -0.03em; }
  #ammo.empty #ammo-mag { color: var(--accent); }
  #ammo-reserve { font-size: 16px; color: var(--muted); }
  #weapon-name { margin-top: 6px; font-size: 13px; color: var(--muted); letter-spacing: .04em; text-transform: uppercase; }

  #topbar { position: fixed; top: 18px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 18px;
    font-family: var(--font-readout); font-size: 14px; background: color-mix(in srgb, var(--canvas) 72%, transparent);
    border: 1px solid var(--hairline); border-radius: var(--radius-panel); padding: 8px 16px; }
  #timer-value { font-size: 20px; }
  #round-label { color: var(--muted); font-size: 12px; letter-spacing: .06em; }
  #score-v { color: var(--vanguard); font-size: 20px; }
  #score-e { color: var(--ember); font-size: 20px; }
  #alive-v { color: var(--vanguard); letter-spacing: 2px; }
  #alive-e { color: var(--ember); letter-spacing: 2px; }

  #money { position: fixed; top: 18px; right: 32px; font-family: var(--font-readout); font-size: 18px; color: var(--accent); }
  #spike-status { position: fixed; top: 64px; left: 50%; transform: translateX(-50%); font-family: var(--font-readout);
    font-size: 13px; letter-spacing: .05em; color: var(--accent); }
  #spike-status.urgent { color: var(--danger); }

  #killfeed { position: fixed; top: 18px; left: 32px; display: grid; gap: 6px; font-size: 13px; color: var(--muted); }
  .feed-line b { color: var(--ink); font-weight: 600; }

  #hint { position: fixed; left: 50%; bottom: 120px; transform: translateX(-50%); font-size: 14px; color: var(--ink);
    background: color-mix(in srgb, var(--canvas) 72%, transparent); border: 1px solid var(--hairline);
    border-radius: var(--radius-panel); padding: 8px 14px; }
  #hint[hidden], #spike-status[hidden], #plant-bar[hidden], #banner[hidden], #buy-menu[hidden] { display: none; }

  #plant-bar { position: fixed; left: 50%; bottom: 160px; transform: translateX(-50%); width: 260px; text-align: center; }
  #plant-track { height: 6px; background: var(--hairline); border-radius: 3px; overflow: hidden; }
  #plant-fill { height: 100%; width: 0; background: var(--accent); }
  #plant-label { margin-top: 6px; font-size: 13px; color: var(--accent); }

  #banner { position: fixed; top: 26%; left: 50%; transform: translateX(-50%); text-align: center; }
  #banner-title { font-size: 44px; font-weight: 600; letter-spacing: .02em; }
  #banner-sub { margin-top: 8px; font-size: 16px; color: var(--muted); }

  .overlay { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px;
    background: color-mix(in srgb, var(--canvas) 86%, transparent); }
  .overlay[hidden] { display: none; }
  .panel { width: min(460px, 100%); padding: 32px; background: var(--surface);
    border: 1px solid var(--hairline); border-radius: var(--radius-panel); }
  .panel h1 { margin: 0 0 8px; font-size: 32px; line-height: 1.15; font-weight: 500; letter-spacing: -0.02em; }
  .panel p { margin: 0 0 24px; max-width: 46ch; font-size: 16px; line-height: 1.5; color: var(--muted); }
  #play { font: inherit; font-weight: 500; padding: 12px 16px; border: 1px solid var(--accent); border-radius: var(--radius-control);
    background: var(--accent); color: var(--canvas); cursor: pointer; }
  #play:hover { background: var(--ink); border-color: var(--ink); }
  .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; gap: 8px; font-size: 14px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
  .keys kbd { min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline); border-radius: var(--radius-panel);
    font-family: var(--font-readout); font-size: 12px; color: var(--ink); text-align: center; }

  #buy-menu { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px;
    background: color-mix(in srgb, var(--canvas) 78%, transparent); pointer-events: auto; }
  #buy-panel { width: min(560px, 100%); padding: 28px; background: var(--surface);
    border: 1px solid var(--hairline); border-radius: var(--radius-panel); }
  #buy-panel h2 { margin: 0 0 4px; font-size: 22px; font-weight: 500; }
  #buy-panel p { margin: 0 0 18px; font-size: 14px; color: var(--muted); }
  #buy-money { font-family: var(--font-readout); color: var(--accent); font-size: 18px; }
  .buy-row { margin-bottom: 8px; }
  .buy-item { width: 100%; display: grid; grid-template-columns: 1fr auto; gap: 2px 12px; text-align: left;
    padding: 10px 12px; background: var(--canvas); border: 1px solid var(--hairline); border-radius: var(--radius-control);
    color: var(--ink); font: inherit; cursor: pointer; }
  .buy-item:hover { border-color: var(--accent); }
  .buy-name { font-weight: 600; }
  .buy-desc { grid-column: 1; font-size: 13px; color: var(--muted); }
  .buy-price { grid-row: 1 / span 2; grid-column: 2; align-self: center; font-family: var(--font-readout); color: var(--accent); }
  #buy-close-hint { margin-top: 14px; font-size: 13px; color: var(--muted); }

  @media (prefers-reduced-motion: reduce) {
    #hitmarker, #damage-flash, #play { transition-duration: 0.01ms; }
  }
</style>
</head>
