    }
  }
  grenade.pos.addScaledVector(grenade.vel, dt);
  if (grenade.pos.y < 0.09) {
    grenade.pos.y = 0.09;
    grenade.vel.y *= -0.45;
    grenade.vel.x *= 0.7;
    grenade.vel.z *= 0.7;
