  if (id === 'armor') {
    if (game.buyArmor()) audio.buy();
    syncHud();
    return;
  }
  if (id === 'grenade') {
    if (s.money >= GRENADE.price && !ownedGrenade) {
      s.money -= GRENADE.price;
      ownedGrenade = true;
      grenadesHeld = 1;
      audio.buy();
