    equip(id, keepAmmo) {
      const def = WEAPONS[id];
      if (!def) return;
      camera.remove(current);
      current = models[id];
      camera.add(current);
      state.id = id;
      state.cooldown = 0;
      state.reloadLeft = 0;
      state.scoped = false;
      if (!keepAmmo) {
        state.mag = def.mag;
        state.reserve = def.reserve;
      }
    },
    refill() {
      const def = WEAPONS[state.id];
      state.mag = def.mag;
      state.reserve = def.reserve;
      state.cooldown = 0;
      state.reloadLeft = 0;
      state.flash = 0;
      state.kick = 0;
      state.scoped = false;
    },
    setScoped(on) {
      state.scoped = on && state.id === 'dmr';
    },
  };
